const XLSX = require("xlsx");
const wb = XLSX.readFile("./testbed/data/order_summary.xlsx");
const data = XLSX.utils.sheet_to_json(wb.Sheets["Orders"]);

// Maya's orders
const maya = data.filter(r => r["Customer"] === "Maya Chen");
console.log("Maya orders:", JSON.stringify(maya, null, 2));

// Item frequency across Maya's confirmed orders
const confirmed = maya.filter(r => r["Status"] === "confirmed");
const items = {};
confirmed.forEach(r => {
  r["Items"].split(", ").forEach(i => { items[i] = (items[i] || 0) + 1; });
});
console.log("\nItem frequency:", JSON.stringify(items, null, 2));
EOF

node << 'SCRIPT'
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  WidthType, AlignmentType, HeadingLevel, BorderStyle, ShadingType
} = require("docx");
const fs = require("fs");

// ── Helpers ──
const hdr = (text, level = HeadingLevel.HEADING_1) =>
  new Paragraph({ heading: level, spacing: { before: 240, after: 120 }, children: [new TextRun({ text, bold: true })] });

const para = (text, opts = {}) =>
  new Paragraph({ spacing: { after: 100 }, children: [new TextRun({ text, ...opts })] });

const bullet = (text) =>
  new Paragraph({ bullet: { level: 0 }, spacing: { after: 60 }, children: [new TextRun(text)] });

const noBorders = {
  top: { style: BorderStyle.NONE, size: 0 },
  bottom: { style: BorderStyle.NONE, size: 0 },
  left: { style: BorderStyle.NONE, size: 0 },
  right: { style: BorderStyle.NONE, size: 0 },
};

const cell = (text, { bold = false, shading = undefined } = {}) =>
  new TableCell({
    borders: noBorders,
    shading,
    width: { size: 100, type: WidthType.AUTO },
    children: [new Paragraph({ children: [new TextRun({ text, bold, size: 20 })] })],
  });

const headerShading = { type: ShadingType.SOLID, color: "2E74B5", fill: "2E74B5" };
const hdrCell = (text) => cell(text, { bold: true, shading: headerShading });

// ── Data ──
const confirmed = [
  { id: "ORD-5B048F", items: "Anker Portable Bluetooth Speaker, LogiTech Wireless Mouse M310", total: "$108" },
  { id: "ORD-542FDA", items: "OXO SoftWorks 3-Piece Mixing Bowl Set, ThermoPro Digital Meat Thermometer", total: "$68" },
  { id: "ORD-D7E869", items: "LogiTech Wireless Mouse M310, OXO SoftWorks 3-Piece Mixing Bowl Set", total: "$71" },
  { id: "ORD-C31654", items: "Wireless Mouse", total: "$29" },
  { id: "ORD-CCC96C", items: "LogiTech Wireless Mouse M310, OXO SoftWorks 3-Piece Mixing Bowl Set, Aurora Smart Desk Lamp Pro", total: "$201" },
];
const cancelled = [
  { id: "ORD-6C71B1", items: "Anker Portable Bluetooth Speaker", total: "$79" },
  { id: "ORD-12AAA3", items: "Wireless Ergonomic Mouse", total: "$39" },
];

const makeRow = (r) => new TableRow({ children: [cell(r.id), cell(r.items), cell(r.total)] });
const headerRow = new TableRow({ children: [hdrCell("Order ID"), hdrCell("Items"), hdrCell("Total Paid")] });

const confirmedTable = new Table({ rows: [headerRow, ...confirmed.map(makeRow)], width: { size: 100, type: WidthType.PERCENTAGE } });
const headerRow2 = new TableRow({ children: [hdrCell("Order ID"), hdrCell("Items"), hdrCell("Total Paid")] });
const cancelledTable = new Table({ rows: [headerRow2, ...cancelled.map(makeRow)], width: { size: 100, type: WidthType.PERCENTAGE } });

// ── Document ──
const doc = new Document({
  creator: "Pi Coding Agent",
  title: "Maya Chen – Order Analysis",
  sections: [{
    children: [
      hdr("Order Analysis — Maya Chen"),
      para("Report Date: 2026-09-02  |  Data Source: order_summary.xlsx", { italics: true, color: "666666" }),

      // Overview
      hdr("1. Overview", HeadingLevel.HEADING_2),
      para("You placed a total of 7 orders on 2026-09-02, making you the most active customer in the dataset (27 orders across all customers). Five orders were confirmed and two were cancelled."),

      // Confirmed
      hdr("2. Confirmed Orders (5) — Subtotal: $477", HeadingLevel.HEADING_2),
      confirmedTable,

      // Cancelled
      hdr("3. Cancelled Orders (2) — Subtotal: $118", HeadingLevel.HEADING_2),
      cancelledTable,

      // Financial
      hdr("4. Financial Summary", HeadingLevel.HEADING_2),
      bullet("Confirmed spend: $477 across 5 orders (avg $95.40 / order)"),
      bullet("Cancelled value: $118 across 2 orders"),
      bullet("Grand total (all orders): $595"),
      bullet("Your confirmed spend alone accounts for ~26% of the day's total confirmed revenue."),
      bullet("Largest single order: ORD-CCC96C at $201 (3 items) — more than double your average."),
      bullet("Smallest order: ORD-C31654 at $29 (single Wireless Mouse)."),

      // Trends
      hdr("5. Trends & Notable Details", HeadingLevel.HEADING_2),

      para("Repeat purchases", { bold: true }),
      bullet("LogiTech Wireless Mouse M310 appears in 3 of your 5 confirmed orders — the most-purchased item."),
      bullet("OXO SoftWorks 3-Piece Mixing Bowl Set also appears 3 times, suggesting a strong preference for kitchen essentials alongside tech accessories."),

      para("Category mix", { bold: true }),
      bullet("Your orders span two distinct categories: tech peripherals (mice, speaker, desk lamp, cable organizer) and kitchen/home goods (mixing bowl set, meat thermometer). This cross-category buying is unique among the top customers in the dataset."),

      para("Cancellation pattern", { bold: true }),
      bullet("Both cancelled orders were single-item orders. In each case, a similar or identical product was later purchased as part of a multi-item confirmed order (e.g., the Anker speaker was cancelled solo but confirmed in a bundle with the LogiTech mouse). This suggests a 'consolidate-and-reorder' behaviour."),

      para("Basket size correlation", { bold: true }),
      bullet("Your multi-item orders average $112 while single-item orders average $29, indicating that bundling drives significantly higher order value."),

      // Recommendations
      hdr("6. Quick Recommendations", HeadingLevel.HEADING_2),
      bullet("Since you reorder the LogiTech Mouse and OXO Bowl Set frequently, consider a subscription or bulk purchase to save on future costs."),
      bullet("The consolidation pattern suggests reviewing your cart before checkout could reduce cancellations."),
      bullet("Your largest order included the Aurora Smart Desk Lamp Pro — complementary smart-home accessories may be worth exploring."),
    ],
  }],
});

Packer.toBuffer(doc).then(buf => {
  fs.writeFileSync("data/maya_chen_order_analysis.docx", buf);
  console.log("Saved: data/maya_chen_order_analysis.docx (" + buf.length + " bytes)");
});
SCRIPT
